  SELECT count(*) INTO v_n FROM pg_constraint con WHERE con.contype = 'f' AND (con.confdeltype IN ('c', 'n', 'd') OR con.confupdtype IN ('n', 'd')) AND (con.conrelid = to_regclass('"ms"."members"') AND con.confrelid = to_regclass('"ms"."chats"'));
  IF v_n = 0 THEN
    missing := missing || E'\n  ' || 'line 100: cascade from ms.chats: no foreign key of ms.members to ms.chats deletes or changes rows of ms.members (ON DELETE CASCADE, SET NULL or SET DEFAULT, ON UPDATE SET NULL or SET DEFAULT): remove the line [AZ625]';
  ELSIF v_n > 1 THEN
    missing := missing || E'\n  ' || 'line 100: cascade from ms.chats: ' || v_n || ' foreign keys of ms.members to ms.chats delete or change rows of ms.members: say which by its columns, cascade from ms.chats (column, ...) [AZ625]';
  END IF;
  SELECT count(*) INTO v_n FROM pg_constraint con WHERE con.contype = 'f' AND (con.confdeltype IN ('c', 'n', 'd') OR con.confupdtype IN ('n', 'd')) AND (con.conrelid = to_regclass('"ms"."members"') AND con.confrelid = to_regclass('"ms"."users"'));
  IF v_n = 0 THEN
    missing := missing || E'\n  ' || 'line 101: cascade from ms.users: no foreign key of ms.members to ms.users deletes or changes rows of ms.members (ON DELETE CASCADE, SET NULL or SET DEFAULT, ON UPDATE SET NULL or SET DEFAULT): remove the line [AZ625]';
  ELSIF v_n > 1 THEN
    missing := missing || E'\n  ' || 'line 101: cascade from ms.users: ' || v_n || ' foreign keys of ms.members to ms.users delete or change rows of ms.members: say which by its columns, cascade from ms.users (column, ...) [AZ625]';
  END IF;
  SELECT count(*) INTO v_n FROM pg_constraint con WHERE con.contype = 'f' AND (con.confdeltype IN ('c', 'n', 'd') OR con.confupdtype IN ('n', 'd')) AND (con.conrelid = to_regclass('"ms"."messages"') AND con.confrelid = to_regclass('"ms"."chats"'));
  IF v_n = 0 THEN
    missing := missing || E'\n  ' || 'line 115: cascade from ms.chats: no foreign key of ms.messages to ms.chats deletes or changes rows of ms.messages (ON DELETE CASCADE, SET NULL or SET DEFAULT, ON UPDATE SET NULL or SET DEFAULT): remove the line [AZ625]';
  ELSIF v_n > 1 THEN
    missing := missing || E'\n  ' || 'line 115: cascade from ms.chats: ' || v_n || ' foreign keys of ms.messages to ms.chats delete or change rows of ms.messages: say which by its columns, cascade from ms.chats (column, ...) [AZ625]';
  END IF;
  SELECT count(*) INTO v_n FROM pg_constraint con WHERE con.contype = 'f' AND (con.confdeltype IN ('c', 'n', 'd') OR con.confupdtype IN ('n', 'd')) AND (con.conrelid = to_regclass('"ms"."messages"') AND con.confrelid = to_regclass('"ms"."users"'));
  IF v_n = 0 THEN
    missing := missing || E'\n  ' || 'line 116: cascade from ms.users: no foreign key of ms.messages to ms.users deletes or changes rows of ms.messages (ON DELETE CASCADE, SET NULL or SET DEFAULT, ON UPDATE SET NULL or SET DEFAULT): remove the line [AZ625]';
  ELSIF v_n > 1 THEN
    missing := missing || E'\n  ' || 'line 116: cascade from ms.users: ' || v_n || ' foreign keys of ms.messages to ms.users delete or change rows of ms.messages: say which by its columns, cascade from ms.users (column, ...) [AZ625]';
  END IF;
  SELECT count(*) INTO v_n FROM pg_constraint con WHERE con.contype = 'f' AND (con.confdeltype IN ('c', 'n', 'd') OR con.confupdtype IN ('n', 'd')) AND (con.conrelid = to_regclass('"ms"."messages"') AND con.confrelid = to_regclass('"ms"."bots"'));
  IF v_n = 0 THEN
    missing := missing || E'\n  ' || 'line 117: cascade from ms.bots: no foreign key of ms.messages to ms.bots deletes or changes rows of ms.messages (ON DELETE CASCADE, SET NULL or SET DEFAULT, ON UPDATE SET NULL or SET DEFAULT): remove the line [AZ625]';
  ELSIF v_n > 1 THEN
    missing := missing || E'\n  ' || 'line 117: cascade from ms.bots: ' || v_n || ' foreign keys of ms.messages to ms.bots delete or change rows of ms.messages: say which by its columns, cascade from ms.bots (column, ...) [AZ625]';
  END IF;
  SELECT count(*) INTO v_n FROM pg_constraint con WHERE con.contype = 'f' AND (con.confdeltype IN ('c', 'n', 'd') OR con.confupdtype IN ('n', 'd')) AND (con.conrelid = to_regclass('"ms"."chat_bots"') AND con.confrelid = to_regclass('"ms"."chats"'));
  IF v_n = 0 THEN
    missing := missing || E'\n  ' || 'line 124: cascade from ms.chats: no foreign key of ms.chat_bots to ms.chats deletes or changes rows of ms.chat_bots (ON DELETE CASCADE, SET NULL or SET DEFAULT, ON UPDATE SET NULL or SET DEFAULT): remove the line [AZ625]';
  ELSIF v_n > 1 THEN
    missing := missing || E'\n  ' || 'line 124: cascade from ms.chats: ' || v_n || ' foreign keys of ms.chat_bots to ms.chats delete or change rows of ms.chat_bots: say which by its columns, cascade from ms.chats (column, ...) [AZ625]';
  END IF;
  SELECT count(*) INTO v_n FROM pg_constraint con WHERE con.contype = 'f' AND (con.confdeltype IN ('c', 'n', 'd') OR con.confupdtype IN ('n', 'd')) AND (con.conrelid = to_regclass('"ms"."chat_bots"') AND con.confrelid = to_regclass('"ms"."bots"'));
  IF v_n = 0 THEN
    missing := missing || E'\n  ' || 'line 125: cascade from ms.bots: no foreign key of ms.chat_bots to ms.bots deletes or changes rows of ms.chat_bots (ON DELETE CASCADE, SET NULL or SET DEFAULT, ON UPDATE SET NULL or SET DEFAULT): remove the line [AZ625]';
  ELSIF v_n > 1 THEN
    missing := missing || E'\n  ' || 'line 125: cascade from ms.bots: ' || v_n || ' foreign keys of ms.chat_bots to ms.bots delete or change rows of ms.chat_bots: say which by its columns, cascade from ms.bots (column, ...) [AZ625]';
  END IF;
  SELECT count(*) INTO v_n FROM pg_constraint con WHERE con.contype = 'f' AND (con.confdeltype IN ('c', 'n', 'd') OR con.confupdtype IN ('n', 'd')) AND (con.conrelid = to_regclass('"ms"."chat_bots"') AND con.confrelid = to_regclass('"ms"."users"'));
  IF v_n = 0 THEN
    missing := missing || E'\n  ' || 'line 126: cascade from ms.users: no foreign key of ms.chat_bots to ms.users deletes or changes rows of ms.chat_bots (ON DELETE CASCADE, SET NULL or SET DEFAULT, ON UPDATE SET NULL or SET DEFAULT): remove the line [AZ625]';
  ELSIF v_n > 1 THEN
    missing := missing || E'\n  ' || 'line 126: cascade from ms.users: ' || v_n || ' foreign keys of ms.chat_bots to ms.users delete or change rows of ms.chat_bots: say which by its columns, cascade from ms.users (column, ...) [AZ625]';
  END IF;
  SELECT count(*) INTO v_n FROM pg_constraint con WHERE con.contype = 'f' AND (con.confdeltype IN ('c', 'n', 'd') OR con.confupdtype IN ('n', 'd')) AND (con.conrelid = to_regclass('"ms"."blocks"') AND con.confrelid = to_regclass('"ms"."users"') AND ARRAY(SELECT a.attname::text FROM pg_attribute a WHERE a.attrelid = con.conrelid AND a.attnum = ANY (con.conkey) ORDER BY a.attname::text COLLATE "C") = ARRAY['blocker_id']::text[]);
  IF v_n = 0 AND (SELECT count(*) FROM pg_attribute WHERE attrelid = to_regclass('"ms"."blocks"') AND attnum > 0 AND NOT attisdropped AND attname = ANY (ARRAY['blocker_id']::name[])) = 1 THEN
    missing := missing || E'\n  ' || 'line 133: cascade from ms.users: no foreign key of ms.blocks to ms.users on (blocker_id) deletes or changes rows of ms.blocks (ON DELETE CASCADE, SET NULL or SET DEFAULT, ON UPDATE SET NULL or SET DEFAULT): remove the line [AZ625]';
  ELSIF v_n > 1 THEN
    missing := missing || E'\n  ' || 'line 133: cascade from ms.users: ' || v_n || ' foreign keys of ms.blocks to ms.users on (blocker_id) delete or change rows of ms.blocks: drop all but one [AZ625]';
  END IF;
  SELECT count(*) INTO v_n FROM pg_constraint con WHERE con.contype = 'f' AND (con.confdeltype IN ('c', 'n', 'd') OR con.confupdtype IN ('n', 'd')) AND (con.conrelid = to_regclass('"ms"."blocks"') AND con.confrelid = to_regclass('"ms"."users"') AND ARRAY(SELECT a.attname::text FROM pg_attribute a WHERE a.attrelid = con.conrelid AND a.attnum = ANY (con.conkey) ORDER BY a.attname::text COLLATE "C") = ARRAY['blocked_id']::text[]);
  IF v_n = 0 AND (SELECT count(*) FROM pg_attribute WHERE attrelid = to_regclass('"ms"."blocks"') AND attnum > 0 AND NOT attisdropped AND attname = ANY (ARRAY['blocked_id']::name[])) = 1 THEN
    missing := missing || E'\n  ' || 'line 134: cascade from ms.users: no foreign key of ms.blocks to ms.users on (blocked_id) deletes or changes rows of ms.blocks (ON DELETE CASCADE, SET NULL or SET DEFAULT, ON UPDATE SET NULL or SET DEFAULT): remove the line [AZ625]';
  ELSIF v_n > 1 THEN
    missing := missing || E'\n  ' || 'line 134: cascade from ms.users: ' || v_n || ' foreign keys of ms.blocks to ms.users on (blocked_id) delete or change rows of ms.blocks: drop all but one [AZ625]';
  END IF;
  IF missing <> '' THEN RAISE EXCEPTION 'the policy does not match this database:%', missing; END IF;
END $chk$;

-- an id as it is stored and compared: '(1, 42)' -> '(1,42)', '007' -> '7', anyone's -> '*' (invalid ids
-- as they are)
CREATE OR REPLACE FUNCTION authz_int.canon(p_type text, p_id text) RETURNS text
LANGUAGE plpgsql STABLE SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  CASE p_type
    WHEN 'user' THEN
      IF pg_catalog.pg_input_is_valid(p_id, 'uuid') THEN RETURN p_id::uuid::text; END IF;
    WHEN 'bot' THEN
      IF pg_catalog.pg_input_is_valid(p_id, 'bigint') THEN RETURN p_id::bigint::text; END IF;
    WHEN 'chat' THEN
      IF pg_catalog.pg_input_is_valid(p_id, 'bigint') THEN RETURN p_id::bigint::text; END IF;
    WHEN 'membership' THEN
      IF pg_catalog.pg_input_is_valid(p_id, 'authz_gen."membership__key"') THEN RETURN p_id::authz_gen."membership__key"::text; END IF;
    WHEN 'message' THEN
      IF pg_catalog.pg_input_is_valid(p_id, 'authz_gen."message__key"') THEN RETURN p_id::authz_gen."message__key"::text; END IF;
    WHEN 'chat_bot' THEN
      IF pg_catalog.pg_input_is_valid(p_id, 'authz_gen."chat_bot__key"') THEN RETURN p_id::authz_gen."chat_bot__key"::text; END IF;
    WHEN 'block' THEN
      IF pg_catalog.pg_input_is_valid(p_id, 'authz_gen."block__key"') THEN RETURN p_id::authz_gen."block__key"::text; END IF;
    WHEN 'anyone' THEN RETURN '*';  -- one subject, whatever id names it
    ELSE NULL;
  END CASE;
  RETURN p_id;
END $f$;

-- shares written directly get canonical ids too
CREATE OR REPLACE FUNCTION authz_int.shares_canon() RETURNS trigger
LANGUAGE plpgsql SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  NEW.object_id := authz_int.canon(NEW.object_type, NEW.object_id);
  NEW.subject_id := authz_int.canon(NEW.subject_type, NEW.subject_id);
  IF NEW.subject_type = 'anyone' THEN NEW.subject_relation := ''; END IF;
  RETURN NEW;
END $f$;

CREATE TRIGGER authz_shares_canon BEFORE INSERT OR UPDATE OF object_type, object_id, subject_type, subject_id,
  subject_relation ON authz.shares FOR EACH ROW EXECUTE FUNCTION authz_int.shares_canon();

-- per-type indexes on share ids, for lookups by object
DO $gi$
DECLARE i record;
BEGIN
  FOR i IN SELECT c.relname FROM pg_index x JOIN pg_class c ON c.oid = x.indexrelid
           WHERE x.indrelid = 'authz.shares'::regclass AND c.relname LIKE 'shares\_obj\_%'
             AND c.relname <> ALL (ARRAY['shares_obj_user_uuid', 'shares_obj_bot_bigint', 'shares_obj_chat_bigint']::text[]) LOOP
    EXECUTE format('DROP INDEX authz.%I', i.relname);
  END LOOP;
END $gi$;
-- @object index authz."shares_obj_user_uuid"
DO $si$
BEGIN
  CREATE INDEX IF NOT EXISTS "shares_obj_user_uuid" ON authz.shares ((object_id::uuid), relation) WHERE object_type = 'user';
EXCEPTION WHEN invalid_text_representation THEN
  RAISE EXCEPTION '%: shares of user whose ids a uuid can''t read were deleted, but a transaction open since before still sees them, and so does the index applying makes of their ids: apply again once it ends, as rowstile help AZ627 says [AZ627]', 'line 7';
END $si$;
-- @object index authz."shares_obj_bot_bigint"
DO $si$
BEGIN
  CREATE INDEX IF NOT EXISTS "shares_obj_bot_bigint" ON authz.shares ((object_id::bigint), relation) WHERE object_type = 'bot';
EXCEPTION WHEN invalid_text_representation THEN
  RAISE EXCEPTION '%: shares of bot whose ids a bigint can''t read were deleted, but a transaction open since before still sees them, and so does the index applying makes of their ids: apply again once it ends, as rowstile help AZ627 says [AZ627]', 'line 13';
END $si$;
-- @object index authz."shares_obj_chat_bigint"
DO $si$
BEGIN
  CREATE INDEX IF NOT EXISTS "shares_obj_chat_bigint" ON authz.shares ((object_id::bigint), relation) WHERE object_type = 'chat';
EXCEPTION WHEN invalid_text_representation THEN
  RAISE EXCEPTION '%: shares of chat whose ids a bigint can''t read were deleted, but a transaction open since before still sees them, and so does the index applying makes of their ids: apply again once it ends, as rowstile help AZ627 says [AZ627]', 'line 18';
END $si$;

-- Share: needs the relation's 'shared by' permission on the object, and every permission
-- the relation grants (you can't grant more than you hold); the subject must exist
CREATE OR REPLACE FUNCTION authz.share(p_type text, p_id text, p_relation text,
  p_subject_type text, p_subject_id text, p_subject_relation text DEFAULT '',
  p_expires_at timestamptz DEFAULT NULL, p_starts_at timestamptz DEFAULT NULL,
  p_caveat text DEFAULT NULL, p_caveat_args jsonb DEFAULT NULL) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_tbl text; v_find text; v_found boolean; v_key text; v_rel authz_int.shared_relations; v_need text;
        v_role authz.roles; v_perms text[];
BEGIN
  PERFORM authz_int.check_writable();
  p_id := authz_int.canon(p_type, p_id);
  p_subject_id := authz_int.canon(p_subject_type, p_subject_id);
  p_subject_relation := CASE WHEN p_subject_type = 'anyone' THEN '' ELSE p_subject_relation END;  -- (no anyone#...)
  IF NOT EXISTS (SELECT 1 FROM authz.principal()) THEN
    RAISE EXCEPTION 'you cannot share % %', p_type, p_id USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  -- lock the object (FOR KEY SHARE): a concurrent delete waits for us, or we for it
  SELECT t.tbl, t.find INTO v_tbl, v_find FROM authz_int.types t WHERE t.name = p_type;
  IF v_tbl IS NULL THEN RAISE EXCEPTION 'no type % in the policy', p_type USING HINT = 'rowstile help AZ707'; END IF;
  IF NOT pg_catalog.pg_input_is_valid(p_id, (SELECT keytype FROM authz_int.types WHERE name = p_type)) THEN
    RAISE EXCEPTION 'you cannot share % %', p_type, p_id USING ERRCODE = 'insufficient_privilege',
      DETAIL = authz_int.share_why(p_type, p_id, '{}'), HINT = 'rowstile help AZ705';
  END IF;
  EXECUTE format('SELECT EXISTS (SELECT 1 FROM %s x WHERE %s FOR KEY SHARE)', v_tbl, v_find) INTO v_found USING p_id;
  -- a caller who may share nothing on the object gets the answer a missing object gets (this same RAISE),
  -- before the subject and the relation are looked at: sharing never tells a hidden object from a missing one
  v_found := v_found AND EXISTS (
    SELECT 1 FROM (SELECT s.shared_by AS perm FROM authz_int.shared_relations s WHERE s.object_type = p_type
                   UNION SELECT 'share') x
    -- (CASE: authz_int.can raises for a permission the type doesn't have, and AND doesn't say which runs first)
    WHERE CASE WHEN EXISTS (SELECT 1 FROM authz_int.perms WHERE type = p_type AND perm = x.perm)
               THEN authz_int.can(p_type, p_id, x.perm) ELSE false END);
  IF NOT v_found THEN
    -- why, in what authz.explain tells the caller (a hidden object as a missing one): the permission sharing this
    -- relation takes (a custom role: share), or for a relation the type doesn't share, each one sharing there takes
    v_perms := CASE WHEN p_relation LIKE 'role:%' THEN ARRAY['share'] ELSE coalesce(
      nullif(ARRAY(SELECT DISTINCT s.shared_by FROM authz_int.shared_relations s
                   WHERE s.object_type = p_type AND s.relation = p_relation), '{}'),
      ARRAY(SELECT s.shared_by FROM authz_int.shared_relations s WHERE s.object_type = p_type UNION SELECT 'share')) END;
    RAISE EXCEPTION 'you cannot share % %', p_type, p_id USING ERRCODE = 'insufficient_privilege',
      DETAIL = authz_int.share_why(p_type, p_id, v_perms), HINT = 'rowstile help AZ705';
  END IF;
  v_key := authz_int.subject_key(p_subject_type, p_subject_id, p_subject_relation);
  -- the subject must exist (and is locked, like the object)
  IF v_key NOT LIKE '%:*' AND v_key NOT IN ('anyone', 'link') THEN
    SELECT t.tbl, t.find INTO v_tbl, v_find FROM authz_int.types t WHERE t.name = p_subject_type;
    v_found := v_tbl IS NOT NULL AND pg_catalog.pg_input_is_valid(p_subject_id,
                 (SELECT keytype FROM authz_int.types WHERE name = p_subject_type));
    IF v_found THEN
      EXECUTE format('SELECT EXISTS (SELECT 1 FROM %s x WHERE %s FOR KEY SHARE)', v_tbl, v_find)
        INTO v_found USING p_subject_id;
    END IF;
    IF NOT v_found THEN
      RAISE EXCEPTION 'there is no % %', p_subject_type, p_subject_id USING HINT = 'rowstile help AZ708';
    END IF;
  END IF;
  IF p_relation LIKE 'role:%' THEN
    -- a custom role: its type must match, the subject must be allowed, and you must hold all it grants
    -- (FOR SHARE: a change to its permissions waits for this share, or this share for it, and weighs what it gives)
    SELECT * INTO v_role FROM authz.roles WHERE 'role:' || id = p_relation FOR SHARE;
    IF v_role.id IS NULL OR v_role.object_type <> p_type THEN
      RAISE EXCEPTION 'no role % for %', p_relation, p_type USING HINT = 'rowstile help AZ706';
    END IF;
    IF NOT authz_int.role_owned(p_type, p_id, v_role.owner_type, v_role.owner_id) THEN
      RAISE EXCEPTION 'role % belongs to % %, which doesn''t own % %', v_role.name, v_role.owner_type, v_role.owner_id,
        p_type, p_id USING HINT = 'rowstile help AZ706';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM authz_int.role_subjects WHERE object_type = p_type AND subject = v_key) THEN
      RAISE EXCEPTION 'custom roles on % cannot be given to %', p_type, v_key USING HINT = 'rowstile help AZ706';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM authz_int.perms WHERE type = p_type AND perm = 'share')
       OR NOT authz_int.can(p_type, p_id, 'share') THEN
      RAISE EXCEPTION 'you cannot share % %', p_type, p_id USING ERRCODE = 'insufficient_privilege',
        DETAIL = authz_int.share_why(p_type, p_id, ARRAY['share']), HINT = 'rowstile help AZ705';
    END IF;
    SELECT string_agg(permission, ', ') INTO v_need FROM authz.role_permissions
    WHERE role_id = v_role.id AND NOT authz_int.can(p_type, p_id, permission);
    IF v_need IS NOT NULL THEN
      RAISE EXCEPTION 'you cannot give role % on % %: you do not hold %', v_role.name, p_type, p_id, v_need
        USING ERRCODE = 'insufficient_privilege', DETAIL = authz_int.share_why(p_type, p_id, string_to_array(v_need, ', ')),
              HINT = 'rowstile help AZ705';
    END IF;
  ELSE
    SELECT * INTO v_rel FROM authz_int.shared_relations s
    WHERE s.object_type = p_type AND s.relation = p_relation AND s.subject = v_key;
    IF v_rel.relation IS NULL THEN
      RAISE EXCEPTION 'the policy does not allow sharing %.% with %', p_type, p_relation, v_key USING HINT = 'rowstile help AZ706';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM authz_int.perms WHERE type = p_type AND perm = v_rel.shared_by)
       OR NOT authz_int.can(p_type, p_id, v_rel.shared_by) THEN
      RAISE EXCEPTION 'you cannot share % % (needs %)', p_type, p_id, v_rel.shared_by USING ERRCODE = 'insufficient_privilege',
        DETAIL = authz_int.share_why(p_type, p_id, ARRAY[v_rel.shared_by]), HINT = 'rowstile help AZ705';
    END IF;
    SELECT string_agg(n, ', ') INTO v_need FROM unnest(v_rel.required) n WHERE NOT authz_int.can(p_type, p_id, n);
    IF v_need IS NOT NULL THEN
      RAISE EXCEPTION 'you cannot grant %.% on % %: you do not hold %', p_type, p_relation, p_type, p_id, v_need
        USING ERRCODE = 'insufficient_privilege', DETAIL = authz_int.share_why(p_type, p_id, string_to_array(v_need, ', ')),
              HINT = 'rowstile help AZ705';
    END IF;
    IF NOT authz_int.share_if(p_type || '.' || p_relation || '.' || v_key, p_id, p_subject_type,
                              p_subject_id, p_subject_relation) THEN
      RAISE EXCEPTION 'the policy does not allow this share (%)', coalesce((SELECT l.loc FROM authz_gen.policy_lines l WHERE l.what = v_rel.loc), '?') USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
    END IF;
  END IF;
  IF p_caveat IS NOT NULL AND NOT EXISTS (SELECT 1 FROM authz_int.caveats WHERE name = p_caveat) THEN
    RAISE EXCEPTION 'no caveat % in the policy', p_caveat USING HINT = 'rowstile help AZ707';
  END IF;
  PERFORM authz_int.mark_row(p_type, p_id);
  IF v_key NOT LIKE '%:*' AND v_key NOT IN ('anyone', 'link') THEN
    PERFORM authz_int.mark_row(p_subject_type, p_subject_id);
  END IF;
  INSERT INTO authz.shares (object_type, object_id, relation, subject_type, subject_id, subject_relation,
                            expires_at, created_by, starts_at, caveat, caveat_args)
  VALUES (p_type, p_id, p_relation, p_subject_type, p_subject_id, p_subject_relation,
          p_expires_at, authz_int.actor(), p_starts_at, p_caveat, p_caveat_args)
  ON CONFLICT ON CONSTRAINT shares_pkey
  DO UPDATE SET expires_at = EXCLUDED.expires_at, created_by = EXCLUDED.created_by,
                starts_at = EXCLUDED.starts_at, caveat = EXCLUDED.caveat, caveat_args = EXCLUDED.caveat_args;
END $f$;

-- Unshare: needs what sharing needs (the relation's 'shared by' permission)
CREATE OR REPLACE FUNCTION authz.unshare(p_type text, p_id text, p_relation text,
  p_subject_type text, p_subject_id text, p_subject_relation text DEFAULT '') RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_by text;
BEGIN
  PERFORM authz_int.check_writable();
  p_id := authz_int.canon(p_type, p_id);
  p_subject_id := authz_int.canon(p_subject_type, p_subject_id);
  p_subject_relation := CASE WHEN p_subject_type = 'anyone' THEN '' ELSE p_subject_relation END;  -- (no anyone#...)
  v_by := coalesce(authz_int.manage_perm(p_type, p_relation,
                                         authz_int.subject_key(p_subject_type, p_subject_id, p_subject_relation)),
                   authz_int.manage_perm(p_type, p_relation));
  -- what it needs comes from the policy alone: the same words for a hidden object and a missing one
  IF NOT EXISTS (SELECT 1 FROM authz.principal()) OR v_by IS NULL
     OR NOT EXISTS (SELECT 1 FROM authz_int.perms WHERE type = p_type AND perm = v_by)
     OR NOT authz_int.can(p_type, p_id, v_by) THEN
    IF v_by IS NULL THEN
      RAISE EXCEPTION 'you cannot unshare % on % %', p_relation, p_type, p_id USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
    END IF;
    RAISE EXCEPTION 'you cannot unshare % on % % (needs %)', p_relation, p_type, p_id, v_by USING ERRCODE = 'insufficient_privilege',
      DETAIL = authz_int.share_why(p_type, p_id, ARRAY[v_by]), HINT = 'rowstile help AZ705';
  END IF;
  DELETE FROM authz.shares WHERE object_type = p_type AND object_id = p_id
    AND relation = p_relation AND subject_type = p_subject_type
    AND subject_id = p_subject_id AND subject_relation = p_subject_relation;
END $f$;

-- The partitions of each table with rules and the tables that inherit from one: row-level security on, with
-- no policies of their own, so they are read and written through it only (read directly, they would skip its rules
-- and triggers). Every apply and every migration: one made or attached since is closed too (it alone is locked,
-- as CHILD_TRIGGERS locks only one that lacks the triggers)
DO $rls$
DECLARE c regclass;
BEGIN
  FOR c IN WITH RECURSIVE d(oid) AS (
             SELECT i.inhrelid FROM pg_catalog.pg_inherits i
             WHERE i.inhparent = ANY (SELECT to_regclass(x)::oid FROM unnest(ARRAY['"ms"."blocks"', '"ms"."bots"', '"ms"."chat_bots"', '"ms"."chats"', '"ms"."members"', '"ms"."messages"', '"ms"."users"']::text[]) x)
             UNION SELECT i.inhrelid FROM pg_catalog.pg_inherits i JOIN d ON i.inhparent = d.oid)
           SELECT d.oid::regclass FROM d JOIN pg_catalog.pg_class k ON k.oid = d.oid WHERE NOT k.relrowsecurity LOOP
    EXECUTE format('ALTER TABLE %s ENABLE ROW LEVEL SECURITY', c);
  END LOOP;
END $rls$;

-- The partitions of a table rowstile watches and the tables that inherit from it: the triggers made above, on
-- each, for the rows stored there and the statements on it
DO $ch$
DECLARE r record;
BEGIN
  FOR r IN SELECT * FROM authz_int.child_triggers() LOOP
    EXECUTE r.stmt;
    EXECUTE pg_catalog.format('COMMENT ON TRIGGER %I ON %s IS %L', r.name, r.child, 'rowstile: the trigger of the table above, for the rows stored here');
  END LOOP;
END $ch$;

